{
  "project_id": "f896356ef18c407a93ae",
  "name": "todos-api",
  "entrypoint_path": "index.ts",
  "import_map_path": "",
  "verify_jwt": true,
  "files": [
    {
      "name": "index.ts",
      "content": "import { createClient } from "npm:@supabase/supabase-js@2";

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8" },
  });

const errorResponse = (message: string, status: number) =>
  json({ error: message }, status);

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

async function readJson(request: Request): Promise<unknown> {
  try {
    return await request.json();
  } catch {
    throw new Error("INVALID_JSON");
  }
}

Deno.serve(async (request) => {
  const url = new URL(request.url);
  const pathname = url.pathname.replace(/\/$/, "");
  const basePath = "/todos-api";
  const authHeader = request.headers.get("Authorization");

  if (!authHeader || !/^Bearer\s+.+/i.test(authHeader)) {
    return errorResponse("Missing authorization", 401);
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    {
      global: {
        headers: { Authorization: authHeader },
      },
    },
  );

  const token = authHeader.replace(/^Bearer\s+/i, "");
  const { data: authData, error: authError } = await supabase.auth.getUser(token);
  const user = authData.user;
  if (authError || !user) {
    return errorResponse("Unauthorized", 401);
  }

  const suffix = pathname.startsWith(`${basePath}/`)
    ? pathname.slice(basePath.length + 1)
    : null;
  const isCollection = pathname === basePath;

  if (!isCollection && suffix === null) {
    return errorResponse("Not found", 404);
  }

  if (suffix !== null && (!suffix || suffix.includes("/"))) {
    return errorResponse("Not found", 404);
  }

  if (suffix !== null && !uuidPattern.test(suffix)) {
    return errorResponse("Invalid UUID path parameter", 400);
  }

  try {
    if (request.method === "GET" && isCollection) {
      const doneParam = url.searchParams.get("done");
      if (doneParam !== null && doneParam !== "true" && doneParam !== "false") {
        return errorResponse("Invalid done query parameter", 400);
      }

      const limitParam = url.searchParams.get("limit");
      let limit = 50;
      if (limitParam !== null) {
        if (!/^[1-9]\d*$/.test(limitParam)) {
          return errorResponse("Invalid limit query parameter", 400);
        }
        limit = Number(limitParam);
        if (!Number.isSafeInteger(limit) || limit < 1 || limit > 100) {
          return errorResponse("Invalid limit query parameter", 400);
        }
      }

      let query = supabase
        .from("todos")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: true })
        .limit(limit);
      if (doneParam !== null) query = query.eq("done", doneParam === "true");

      const { data, error } = await query;
      if (error) {
        console.error(error);
        return errorResponse("Database failure", 500);
      }
      return json(data);
    }

    if (request.method === "POST" && isCollection) {
      let payload: unknown;
      try {
        payload = await readJson(request);
      } catch {
        return errorResponse("Invalid JSON", 400);
      }
      if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
        return errorResponse("Invalid request body", 400);
      }

      const { body, done } = payload as Record<string, unknown>;
      if (typeof body !== "string" || body.trim().length === 0) {
        return errorResponse("body must be a non-empty string", 400);
      }
      if (done !== undefined && typeof done !== "boolean") {
        return errorResponse("done must be a boolean", 400);
      }

      const { data, error } = await supabase
        .from("todos")
        .insert({ user_id: user.id, body, done: done ?? false })
        .select()
        .single();
      if (error) {
        console.error(error);
        return errorResponse("Database failure", 500);
      }
      return json(data, 201);
    }

    if (request.method === "PATCH" && suffix !== null) {
      let payload: unknown;
      try {
        payload = await readJson(request);
      } catch {
        return errorResponse("Invalid JSON", 400);
      }
      if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
        return errorResponse("Invalid request body", 400);
      }

      const values = payload as Record<string, unknown>;
      const keys = Object.keys(values);
      if (keys.length === 0 || keys.some((key) => key !== "body" && key !== "done")) {
        return errorResponse("Only body and done may be updated", 400);
      }
      if ("body" in values && (typeof values.body !== "string" || values.body.trim().length === 0)) {
        return errorResponse("body must be a non-empty string", 400);
      }
      if ("done" in values && typeof values.done !== "boolean") {
        return errorResponse("done must be a boolean", 400);
      }

      const updates: Record<string, string | boolean> = {};
      if ("body" in values) updates.body = values.body as string;
      if ("done" in values) updates.done = values.done as boolean;

      const { data, error } = await supabase
        .from("todos")
        .update(updates)
        .eq("id", suffix)
        .eq("user_id", user.id)
        .select()
        .maybeSingle();
      if (error) {
        console.error(error);
        return errorResponse("Database failure", 500);
      }
      if (!data) return errorResponse("Todo not found", 404);
      return json(data);
    }

    if (request.method === "DELETE" && suffix !== null) {
      const { data, error } = await supabase
        .from("todos")
        .delete()
        .eq("id", suffix)
        .eq("user_id", user.id)
        .select("id")
        .maybeSingle();
      if (error) {
        console.error(error);
        return errorResponse("Database failure", 500);
      }
      if (!data) return errorResponse("Todo not found", 404);
      return json({ deleted: true });
    }

    return errorResponse("Method not allowed", 405);
  } catch (error) {
    console.error(error);
    return errorResponse("Database failure", 500);
  }
});
"
    }
  ]
}

